-- Security and Patrol -- complete content database: schema AND data.
-- This single file creates every table (empty tables first, further down
-- this file) AND fills them with the site's real, current content (the
-- INSERT statements after the "Starting data below" marker) — importing
-- just this one file is enough to get a fully working, populated database.
-- No other script needs to run afterward.
--
-- Run with: mysql -u root < database/schema.sql
-- (or: phpMyAdmin -> Import -> choose this file -> Go)
--
-- Design: each content type a client would realistically want to edit gets its
-- own table (services, offices, blog_posts). Whole-page sections that are still
-- large free-form HTML (contact page, offices page wrapper, etc.) live in
-- `pages`, keyed by slug, so they can still be edited from the database without
-- redeploying code. `content_blocks` holds smaller named chunks (e.g. individual
-- home-page sections) that don't warrant their own table. `site_settings` holds
-- single values reused across the site (phone number, email, social links).

-- CREATE DATABASE IF NOT EXISTS securityand_patrol
--   CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE aviorcon_security;

-- Whole-page HTML content, one row per route (contact-us, offices, home sections
-- not yet broken into their own tables, privacy-policy, career, etc.)
CREATE TABLE IF NOT EXISTS pages (
  id INT AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(191) NOT NULL UNIQUE,
  title VARCHAR(255) NOT NULL,
  meta_description TEXT NULL,
  content_html LONGTEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Named, independently-editable content chunks within a page (a hero heading,
-- an intro paragraph, a why-choose blurb, etc.) so small edits don't require
-- rewriting a whole page's HTML blob.
CREATE TABLE IF NOT EXISTS content_blocks (
  id INT AUTO_INCREMENT PRIMARY KEY,
  page_slug VARCHAR(191) NOT NULL,
  block_key VARCHAR(191) NOT NULL,
  block_type ENUM('html', 'text', 'image', 'json') NOT NULL DEFAULT 'html',
  title VARCHAR(255) NULL,
  content LONGTEXT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_page_block (page_slug, block_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per service (Armed Security, Unarmed Security, Event Security, ...).
CREATE TABLE IF NOT EXISTS services (
  id INT AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(191) NOT NULL UNIQUE,
  wp_id INT NULL,
  title VARCHAR(255) NOT NULL,
  summary VARCHAR(500) NULL,
  seo_title VARCHAR(255) NULL,
  seo_description TEXT NULL,
  content_html LONGTEXT NOT NULL,
  -- Plain data describing where the on-page heading lives inside
  -- content_html (a raw HTML blob of scraped page markup) — no HTML is
  -- stored here, only a tag name and a position. On every read, the
  -- heading_occurrence-th <heading_tag class="elementor-heading-title...">
  -- tag found in content_html has its text replaced with the current
  -- `title` (plus heading_subtitle, if set) — this is built in code, not
  -- stored — so editing `title` changes the visible heading without ever
  -- writing HTML into the database. heading_tag NULL means no on-page
  -- heading edit is wired up for this row.
  heading_tag VARCHAR(2) NULL,
  heading_occurrence INT NOT NULL DEFAULT 0,
  heading_subtitle VARCHAR(255) NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per office/branch location.
CREATE TABLE IF NOT EXISTS offices (
  id INT AUTO_INCREMENT PRIMARY KEY,
  anchor VARCHAR(100) NULL,
  name VARCHAR(255) NOT NULL,
  license_number VARCHAR(100) NULL,
  office_type VARCHAR(100) NULL,
  address TEXT NULL,
  phone VARCHAR(50) NULL,
  image_url VARCHAR(500) NULL,
  image_alt VARCHAR(500) NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per blog post.
CREATE TABLE IF NOT EXISTS blog_posts (
  id INT AUTO_INCREMENT PRIMARY KEY,
  wp_id INT NULL,
  slug VARCHAR(191) NOT NULL UNIQUE,
  title VARCHAR(500) NOT NULL,
  excerpt TEXT NULL,
  content_html LONGTEXT NOT NULL,
  featured_image_url VARCHAR(500) NULL,
  featured_image_alt VARCHAR(500) NULL,
  author VARCHAR(255) NULL,
  categories JSON NULL,
  seo_title VARCHAR(255) NULL,
  seo_description TEXT NULL,
  audio_url VARCHAR(500) NULL,
  published_at DATETIME NULL,
  modified_at DATETIME NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Single reusable values shared across the site (phone number, emails, social
-- links, company name) so a client can update them in one place.
CREATE TABLE IF NOT EXISTS site_settings (
  setting_key VARCHAR(191) PRIMARY KEY,
  setting_value TEXT NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

